export function findPrivilegedClientBodyKeys(
  body: unknown,
): PrivilegedClientBodyKey[] {
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    return [];
  }
  const found: PrivilegedClientBodyKey[] = [];
  for (const key of Object.keys(body as Record<string, unknown>)) {
    if (PRIVILEGED.has(key)) {
      found.push(key as PrivilegedClientBodyKey);
    }
  }
  return found;
}

export function privilegedClientBodyRejectionMessage(
  body: unknown,
): string | null {
  const found = findPrivilegedClientBodyKeys(body);
  if (found.length === 0) return null;
  return `Client darf privilegierte Felder nicht setzen: ${found.join(', ')}`;
}

export type CorsOptions = {
  /** Override Allow-Methods (e.g. "POST, OPTIONS" for POST-only functions). */
  methods?: string;
  allowHeaders?: string;
  /**
   * Env keys tried in order for the allowlist CSV (or explicit `*`).
   * Default: CHARACTER_AI_ALLOWED_ORIGIN
   */
  envKeys?: string[];
  /** When true (default), include Content-Type: application/json on CORS header bags. */
  includeJsonContentType?: boolean;
  /**
   * When origin does not match allowlist/localhost:
   * - omit (default): do not set Access-Control-Allow-Origin (fail-closed)
   * - configured-or-star: set configured value or `*` (legacy meshy fallback)
   */
  missingOriginPolicy?: 'omit' | 'configured-or-star';
  /** When true, echo localhost even if an allowlist env is set (legacy meshy). */
  allowLocalhostWhenConfigured?: boolean;
};

function readConfiguredOrigin(envKeys: string[]): string {
  for (const key of envKeys) {
    const value = Deno.env.get(key)?.trim() ?? '';
    if (value) return value;
  }
  return '';
}

export function isLocalDevOrigin(origin: string): boolean {
  return /^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/i.test(origin);
}

export function corsHeaders(
  request: Request,
  opts: CorsOptions = {},
): Record<string, string> {
  const envKeys = opts.envKeys?.length
    ? opts.envKeys
    : ['CHARACTER_AI_ALLOWED_ORIGIN'];
  const configured = readConfiguredOrigin(envKeys);
  const requestOrigin = request.headers.get('Origin');
  const headers: Record<string, string> = {
    'Access-Control-Allow-Methods': opts.methods ?? DEFAULT_CORS_METHODS,
    'Access-Control-Allow-Headers':
      opts.allowHeaders ?? DEFAULT_CORS_ALLOW_HEADERS,
    Vary: 'Origin',
  };

  if (opts.includeJsonContentType !== false) {
    headers['Content-Type'] = 'application/json';
  }

  if (configured === '*') {
    headers['Access-Control-Allow-Origin'] = '*';
    return headers;
  }

  const allowlist = configured
    .split(',')
    .map((entry) => entry.trim())
    .filter(Boolean);

  if (requestOrigin && allowlist.includes(requestOrigin)) {
    headers['Access-Control-Allow-Origin'] = requestOrigin;
    return headers;
  }

  const localhostOk =
    Boolean(requestOrigin) &&
    isLocalDevOrigin(requestOrigin!) &&
    (!configured || opts.allowLocalhostWhenConfigured === true);

  if (localhostOk && requestOrigin) {
    headers['Access-Control-Allow-Origin'] = requestOrigin;
    return headers;
  }

  if (opts.missingOriginPolicy === 'configured-or-star') {
    headers['Access-Control-Allow-Origin'] = configured || '*';
  }

  return headers;
}

export function handleOptions(
  request: Request,
  opts?: CorsOptions,
): Response | null {
  if (request.method !== 'OPTIONS') return null;
  return new Response(null, {
    status: 204,
    headers: corsHeaders(request, opts),
  });
}

export function jsonResponse(
  request: Request,
  body: unknown,
  status = 200,
  opts?: CorsOptions,
): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: corsHeaders(request, opts),
  });
}

export type EdgeMediaGrant = {
  canPublish: boolean;
  canSubscribe: boolean;
  canPublishData: boolean;
  receiveOnly: boolean;
};

export function deriveMediaRoomId(sessionId: string): string {
  return `sagatree-session-${sessionId.trim()}`;
}

export function resolveEdgeMediaGrant(input: {
  role: string;
  capabilities?: string[];
}): EdgeMediaGrant | null {
  const role = input.role.trim().toLowerCase();
  const normalized =
    role === 'gm' ? 'gamemaster' : role === 'observer' ? 'viewer' : role;
  if (
    normalized !== 'player' &&
    normalized !== 'gamemaster' &&
    normalized !== 'viewer'
  ) {
    return null;
  }
  const caps = Array.isArray(input.capabilities) ? input.capabilities : [];
  const isDirector = caps.map((c) => c.toLowerCase()).includes('director');
  const canPublish =
    normalized === 'player' || normalized === 'gamemaster';
  const canSubscribe =
    normalized === 'viewer' ||
    normalized === 'player' ||
    normalized === 'gamemaster' ||
    isDirector;
  return {
    canPublish,
    canSubscribe,
    canPublishData: canPublish,
    receiveOnly: normalized === 'viewer' && !isDirector,
  };
}

function base64Url(bytes: Uint8Array): string {
  let binary = '';
  for (const b of bytes) binary += String.fromCharCode(b);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

function base64UrlJson(value: unknown): string {
  return base64Url(new TextEncoder().encode(JSON.stringify(value)));
}

async function hmacSha256(secret: string, data: string): Promise<Uint8Array> {
  const key = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  );
  const sig = await crypto.subtle.sign(
    'HMAC',
    key,
    new TextEncoder().encode(data),
  );
  return new Uint8Array(sig);
}

export async function mintLiveKitAccessToken(input: {
  apiKey: string;
  apiSecret: string;
  identity: string;
  roomName: string;
  ttlSeconds: number;
  grant: EdgeMediaGrant;
}): Promise<{ token: string; expiresAt: string }> {
  const now = Math.floor(Date.now() / 1000);
  const exp = now + input.ttlSeconds;
  const header = { alg: 'HS256', typ: 'JWT' };
  const payload = {
    iss: input.apiKey,
    sub: input.identity,
    nbf: now - 10,
    exp,
    iat: now,
    name: input.identity,
    video: {
      roomJoin: true,
      room: input.roomName,
      canPublish: input.grant.canPublish,
      canSubscribe: input.grant.canSubscribe,
      canPublishData: input.grant.canPublishData,
    },
  };
  const body = `${base64UrlJson(header)}.${base64UrlJson(payload)}`;
  const sig = await hmacSha256(input.apiSecret, body);
  return {
    token: `${body}.${base64Url(sig)}`,
    expiresAt: new Date(exp * 1000).toISOString(),
  };
}

CORS_OPTS: CorsOptions = {
  methods: 'POST, OPTIONS',
  missingOriginPolicy: 'configured-or-star',
}

function json(req: Request, body: JsonRecord, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders(req, CORS_OPTS),
      'Content-Type': 'application/json',
    },
  });
}

function readEnv(name: string): string {
  return Deno.env.get(name)?.trim() ?? '';
}

async function getUserId(
  request: Request,
  supabaseUrl: string,
  anonKey: string,
): Promise<string | null> {
  const auth = request.headers.get('Authorization');
  if (!auth) return null;
  const res = await fetch(`${supabaseUrl}/auth/v1/user`, {
    headers: { Authorization: auth, apikey: anonKey },
  });
  if (!res.ok) return null;
  const body = (await res.json()) as { id?: string };
  return typeof body.id === 'string' ? body.id : null;
}

type MembershipRow = {
  user_id: string;
  role: string;
  capabilities: string[] | null;
  character_id: string | null;
};

async function loadMembership(input: {
  supabaseUrl: string;
  serviceRoleKey: string;
  sessionId: string;
  userId: string;
}): Promise<MembershipRow | null> {
  // Prefer project_members via session → project; fall back to session_players demo table shape.
  const headers = {
    Authorization: `Bearer ${input.serviceRoleKey}`,
    apikey: input.serviceRoleKey,
    'Content-Type': 'application/json',
  };

  const sessionRes = await fetch(
    `${input.supabaseUrl}/rest/v1/sessions?id=eq.${encodeURIComponent(input.sessionId)}&select=id,project_id`,
    { headers },
  );
  if (!sessionRes.ok) return null;
  const sessions = (await sessionRes.json()) as Array<{
    id: string;
    project_id: string;
  }>;
  if (!Array.isArray(sessions) || sessions.length === 0) return null;
  const projectId = sessions[0]!.project_id;

  const memberRes = await fetch(
    `${input.supabaseUrl}/rest/v1/project_members?project_id=eq.${encodeURIComponent(projectId)}&user_id=eq.${encodeURIComponent(input.userId)}&status=eq.active&select=user_id,role,character_id`,
    { headers },
  );
  if (!memberRes.ok) return null;
  const members = (await memberRes.json()) as Array<{
    user_id: string;
    role: string;
    character_id: string | null;
  }>;
  if (!Array.isArray(members) || members.length === 0) return null;
  const row = members[0]!;
  return {
    user_id: row.user_id,
    role: row.role,
    capabilities: null,
    character_id: row.character_id,
  };
}
